-- Padrão Brasil oficial (IBGE): SIRGAS 2000 em UTM zona 23S
-- EPSG:31983 — distâncias em metros, área em m²

CREATE TABLE talhoes (
  id BIGSERIAL PRIMARY KEY,
  nome TEXT NOT NULL,
  area_calc DOUBLE PRECISION GENERATED ALWAYS AS (ST_Area(geom)) STORED,
  geom GEOMETRY(Polygon, 31983) NOT NULL
);

CREATE INDEX talhoes_geom_gix ON talhoes USING GIST (geom);

-- Para "estabelecimentos com raio de 500m do usuário" global, prefira geography:
CREATE TABLE estabelecimentos (
  id BIGSERIAL PRIMARY KEY,
  nome TEXT NOT NULL,
  loc GEOGRAPHY(Point, 4326) NOT NULL
);

CREATE INDEX estab_loc_gix ON estabelecimentos USING GIST (loc);
